  function helpDialog(){const d=modal("How to use",'tc-help-dialog');d.innerHTML=`<header><strong>Make room in your day for what matters</strong>${button('close-dialog',icons.close,"aria-label=\"Close help\"")}</header><ol><li><b>Jot it down.</b>Click “New” at the top right and enter a name. Tasks without a group appear in Inbox.</li><li><b>Drag to the calendar.</b>Drop on a date for an all-day task, or on the timeline to set a time.</li><li><b>Adjust the duration.</b>Hover over a task's top or bottom edge to see resize handles. Drag the body to move it. Press Esc to cancel.</li><li><b>Group and complete.</b>Choose or add a group in details. Drag to Inbox to remove its group while keeping its schedule. Click the circle to complete, or the name to edit.</li><li><b>Find it again.</b>Switch between Calendar, Board and Matrix at the bottom left. Board shows all tasks by group, including unscheduled and completed tasks. Matrix groups by priority. Recently Deleted keeps tasks for 30 days.</li></ol><p>On touchscreens, hold a task to drag. You can also enter dates, times and groups directly in details.</p><p>Tasks are stored per account in this browser. Export or import backups below. They don't sync to other devices automatically.</p><div class="tc-dialog-actions">${button('examples',"Add examples")}${button('clear-examples',"Clear examples")}${button('export',"Export backup")}${button('import',"Import backup")}${button('close-dialog',"Get started",'','tc-primary')}</div>`;d.showModal();}
